class Question {
  final int id;
  final String category;
  final String text;
  final List<String> options;
  final int correctIndex;
  final String explanation;
  final String topicId;
  final bool isVerified;

  const Question({
    required this.id,
    required this.category,
    required this.text,
    required this.options,
    required this.correctIndex,
    required this.explanation,
    String topicId = '',
    this.isVerified = false,
  }) : topicId = (topicId == 'arv2_lenkzeiten'
            ? 'arv2_lenkzeit'
            : topicId == 'arv2_arbeitszeiten'
                ? 'arv2_arbeitszeit'
                : topicId == 'arv2_ruhezeiten'
                    ? 'arv2_ruhezeit'
                    : topicId == 'arv2_fahrtschreiber'
                        ? 'arv2_dokumentation'
                        : topicId);
}

class QuestionTopic {
  final String id;
  final String titleDe;
  final String titleFr;
  final String titleIt;
  final String descriptionDe;
  final String descriptionFr;
  final String descriptionIt;

  const QuestionTopic({
    required this.id,
    required this.titleDe,
    required this.titleFr,
    required this.titleIt,
    required this.descriptionDe,
    required this.descriptionFr,
    required this.descriptionIt,
  });

  String get title => titleDe;
  String get description => descriptionDe;

  static List<QuestionTopic> get sampleTopics => sampleBpt121Topics;

  String getTitle(String lang) {
    switch (lang) {
      case 'fr':
        return titleFr;
      case 'it':
        return titleIt;
      case 'de':
      default:
        return titleDe;
    }
  }

  String getDescription(String lang) {
    switch (lang) {
      case 'fr':
        return descriptionFr;
      case 'it':
        return descriptionIt;
      case 'de':
      default:
        return descriptionDe;
    }
  }
}

