/// Standart İsviçre BPT 121 sınav altyapısı sabitleri (30 soru / 27 doğru / %90)
const int officialExamQuestionCount = 30;
const int officialPassingScore = 27;

/// Sınavı geçmek için gereken minimum doğru sayısını hesaplar.
/// 30 soruluk resmi sınavda doğrudan 27 doğru (%90) gerektirir.
/// Farklı soru sayılarında %90 yukarı yuvarlanarak hesaplanır.
int calculateRequiredPassingScore(int totalQuestions) {
  if (totalQuestions == officialExamQuestionCount) {
    return officialPassingScore;
  }
  return (totalQuestions * 0.9).ceil();
}

/// Sınavın başarılı sayılıp sayılmadığını kontrol eder.
bool isExamPassed(int score, int totalQuestions) {
  return score >= calculateRequiredPassingScore(totalQuestions);
}

